// Technique guidance: PF Concept decoration guides and product-specific limits.
// https://www.pfconcept.com/en_nl/padprint
// https://thedigitalcatalogue.pfconcept.com/pdf/2021_main/office_hoi_2021.pdf
const methods = [
 [/360.*digital/i,'Farver hele vejen rundt.','Digitaltryk rundt om produktet. Godt til billeder og farveovergange. Det viste trykområde afgør, hvor meget der kan dækkes.','Colour around the product.','Digital printing around the product, suitable for images and gradients. Coverage depends on the displayed print area.'],
 [/360.*(grav|engrav)/i,'Gravering rundt om produktet.','Motivet graveres rundt om produktet uden trykfarve. Farven afhænger af materiale og belægning. Se det tilgængelige trykområde.','Engraving around the product.','The design is engraved around the product without ink. Colour depends on the material and coating. Check the available decoration area.'],
 [/3d.*(brod|embro)/i,'Logo syet med hævet effekt.','Tråd giver logoet en hævet effekt. Enkle, tydelige former er bedst; små detaljer skal vurderes i korrekturen.','Raised, stitched logo.','Thread creates a raised effect. Simple, clear shapes work best; fine details need checking in the proof.'],
 [/brod|embro/i,'Logo syet med tråd.','Logoet sys i stoffet. Tråden giver struktur; meget lille tekst og farveovergange egner sig bedre til tryk.','Logo stitched with thread.','The logo is stitched into the fabric. Thread adds texture; very small text and gradients are better suited to printing.'],
 [/doming/i,'Blankt logomærke med 3D-effekt.','Et trykt mærke dækkes med klar harpiks, som giver en blank, hævet overflade.','Glossy label with a 3D effect.','A printed label is covered with clear resin to create a glossy, raised surface.'],
 [/folie|foil|hot.?stamp/i,'Logo med folieeffekt.','Et speciallavet stempel overfører folie til produktet med varme og tryk. Det giver logoet fx guld- eller sølvfinish. Hvor tydeligt logoet præges ned, afhænger af materialet.','Logo with a foil finish.','A custom-made die transfers foil to the product using heat and pressure, giving the logo a finish such as gold or silver. How deeply the logo is pressed into the surface depends on the material.'],
 [/prægning|deboss|emboss/i,'Logo præget i overfladen.','Motivet presses i materialet og giver struktur uden almindelig trykfarve. Kontrasten afhænger af materialet.','Logo pressed into the surface.','The design is pressed into the material, adding texture without standard printing ink. Contrast depends on the material.'],
 [/rundtryk|screenround/i,'Tryk langs en rund flade.','Serigrafi, hvor produktet drejes under tryk. Velegnet til tydelige logoer og tekst i enkelte farver.','Print around a curved surface.','Screen printing with the product rotating during printing. Suitable for clear logos and text in solid colours.'],
 [/sublimation/i,'Farver, der bindes i overfladen.','Varme overfører farven til egnet polyester eller belægning. Velegnet til farverige motiver; resultatet afhænger af underlaget.','Colour bonded into the surface.','Heat transfers colour into suitable polyester or a coating. Suitable for colourful designs; the result depends on the base material.'],
 [/tampon|pad.?print/i,'Små logoer på buede flader.','En blød silikonepude overfører farven til produktet. Godt til enkle logoer på fx kuglepenne og krus. Hver farve trykkes separat; fotos og farveovergange egner sig bedre til digitaltryk.','Small logos on curved surfaces.','A soft silicone pad transfers ink to the product. Good for simple logos on pens and mugs. Colours are printed separately; photos and gradients are better suited to digital printing.'],
 [/serigrafi|screen.?print/i,'Tydelige logoer i faste farver.','Farven trykkes gennem en skabelon i en fin dug. Godt til ensfarvede flader og enkle logoer; hver farve kræver sin egen skabelon.','Clear logos in solid colours.','Ink is pushed through a stencil in a fine mesh. Good for solid areas and simple logos; each colour needs its own stencil.'],
 [/laser|grav|engrav/i,'Logo graveret uden trykfarve.','En laser mærker overfladen. Logoet får materialets eller det underliggende lags farve, ikke en valgfri trykfarve. Nuancen afhænger af produktet.','Logo engraved without ink.','A laser marks the surface. The logo takes the colour of the material or underlying layer rather than a chosen ink colour. The shade depends on the product.'],
 [/digital.*transfer|dtf/i,'Detaljerede farvemotiver på stof.','Motivet trykkes på en film og overføres med varme. Godt til flere farver og detaljer; trykket ligger oven på stoffet.','Detailed colour designs on fabric.','The design is printed on a film and heat-transferred. Good for multiple colours and detail; the print sits on top of the fabric.'],
 [/transfer/i,'Motiv overført med varme.','Motivet fremstilles separat og presses på produktet med varme. Antal farver og detaljer afhænger af den konkrete transfermetode.','Design applied using heat.','The design is made separately and heat-pressed onto the product. Colour and detail options depend on the specific transfer technique.'],
 [/klistermærke|sticker/i,'Motiv på en selvklæbende etiket.','Motivet trykkes på en etiket, som sættes på produktet. Egnet til detaljer og flere farver.','Design on an adhesive label.','The design is printed on a label and attached to the product. Suitable for details and multiple colours.'],
 [/digital/i,'Billeder og mange farver.','Motivet trykkes digitalt på overfladen. Godt til detaljer, fotos og farveovergange. Farver kan opleves anderledes på produktet end på en skærm.','Images and multiple colours.','The design is printed digitally onto the surface. Good for details, photos and gradients. Colours may look different on the product than on a screen.'],
 [/printpapir|litho|litografi|mat paper|matte papir|web offset/i,'Motiv trykt på papir.','Tryk til tekst og billeder på papir. Papirets overflade påvirker farver og udtryk.','Design printed on paper.','Printing for text and images on paper. The paper surface affects the colours and appearance.'],
 [/oplyst logo|light.?up/i,'Logo, der lyser op.','Logoet fremhæves af produktets indbyggede lys. Udtrykket afhænger af produktets lys og overflade.','A logo that lights up.','The logo is highlighted by the product’s built-in light. Its appearance depends on the light and surface.'],
];
export function printMethodHelp(name,language='da') {
 const match=methods.find(([pattern])=>pattern.test(String(name||'')));
 const en=language==='en';
 return match?{short:match[en?3:1],detail:match[en?4:2]}:{short:en?'Decoration adapted to this product.':'Dekoration tilpasset produktet.',detail:en?'The available area and colour options are shown for this product. Contact us if you need help choosing.':'De mulige områder og farver vises for dette produkt. Kontakt os, hvis du er i tvivl om valget.'};
}
